        "SecutgExportWarning": ["en": "This file plus the transfer code is your whole encryption identity: whoever holds both can read every encrypted chat of yours and impersonate you. Send the code through a different channel than the file, and delete both once the other device is done.", "zh-Hans": "这个文件加上搬运码等于你的全部加密身份，拿到的人能解读你所有加密聊天并冒充你。请通过与文件不同的渠道传搬运码，另一台设备导入完成后把两者都删掉。", "zh-Hant": "這個檔案加上搬運碼等於你的全部加密身分，拿到的人能解讀你所有加密聊天並冒充你。請透過與檔案不同的渠道傳搬運碼，另一台裝置匯入完成後把兩者都刪掉。"],
        "SecutgFaqRow": ["en": "FAQ", "zh-Hans": "常见问题", "zh-Hant": "常見問題"],
        "SecutgFilterUndecryptable": ["en": "Fold messages I cannot decrypt", "zh-Hans": "折叠解不开的消息", "zh-Hant": "摺疊解不開的訊息"],
        "SecutgFilterUndecryptableHint": ["en": "Runs of messages this device has no key for collapse into one line you can tap open. They are never removed, and unread counts are unaffected.", "zh-Hans": "本机没有密钥的消息会合并成一行，点一下展开。消息不会被删除，未读计数也不受影响。", "zh-Hant": "本機沒有金鑰的訊息會合併成一行，點一下展開。訊息不會被刪除，未讀計數也不受影響。"],
        "SecutgForwardReencrypted": ["en": "{count} forwarded messages were re-sent encrypted, so they lost the forwarded-from label", "zh-Hans": "{count} 条转发消息已改为加密重发，因此不再带「转发自」标记", "zh-Hant": "{count} 則轉發訊息已改為加密重發，因此不再帶「轉發自」標記"],
        "SecutgForwardSecrecyDisabled": ["en": "Forward secrecy off", "zh-Hans": "前向保密已关闭", "zh-Hant": "前向保密已關閉"],
        "SecutgForwardSecrecyEnabled": ["en": "Forward secrecy on: the key now changes daily", "zh-Hans": "前向保密已开启：密钥每天自动更换", "zh-Hant": "前向保密已開啟：金鑰每天自動更換"],
        "SecutgForwardSecrecyOffHint": ["en": "Daily rotation stops and a fixed key is used again. Old daily keys that were already destroyed do not come back.", "zh-Hans": "关闭后回到固定主钥。已销毁的旧日钥匙不会恢复。", "zh-Hant": "關閉後回到固定主鑰。已銷毀的舊日鑰匙不會恢復。"],
        "SecutgForwardSecrecyOnHint": ["en": "The chat key will change every day and yesterday’s keys are destroyed on both devices. Messages already cached on this device stay readable, but history re-downloaded from the server can no longer be decrypted, and a new device cannot read old messages at all. The other side follows automatically.", "zh-Hans": "开启后主钥每天自动更换，昨天的钥匙在双方设备上销毁。本设备已缓存的消息仍可见，但重新从服务器拉取的历史消息将无法解密，换设备后完全读不了。对方设备会自动跟随。", "zh-Hant": "開啟後主鑰每天自動更換，昨天的鑰匙在雙方裝置上銷毀。本裝置已快取的訊息仍可見，但重新從伺服器拉取的歷史訊息將無法解密，換裝置後完全讀不了。對方裝置會自動跟隨。"],
        "SecutgForwardSecrecyTitle": ["en": "Forward secrecy", "zh-Hans": "前向保密", "zh-Hant": "前向保密"],
        "SecutgForwardSecrecyTurnOff": ["en": "Turn off", "zh-Hans": "关闭", "zh-Hant": "關閉"],
        "SecutgForwardSecrecyTurnOn": ["en": "I understand, turn on", "zh-Hans": "我已了解，开启", "zh-Hant": "我已了解，開啟"],
        "SecutgForwardedFrom": ["en": "Forwarded from {name}", "zh-Hans": "转发自 {name}", "zh-Hant": "轉發自 {name}"],
        "SecutgG2NoConfidentiality": ["en": "Obfuscated, not confidential from Telegram", "zh-Hans": "混淆模式，对 Telegram 平台不提供保密性", "zh-Hant": "混淆模式，對 Telegram 平台不提供保密性"],
        "SecutgGroupKeyAccepted": ["en": "The new key was accepted.", "zh-Hans": "已接受这把新密钥。", "zh-Hant": "已接受這把新密鑰。"],
        "SecutgGroupKeyApplied": ["en": "🔑 {name} published a new group key. This chat now uses it.", "zh-Hans": "🔑 {name} 发布了新的群密钥，本群已启用。", "zh-Hant": "🔑 {name} 發佈了新的群密鑰，本群已啟用。"],
        "SecutgGroupKeyByYou": ["en": "🔑 You published a new group key.", "zh-Hans": "🔑 你发布了新的群密钥。", "zh-Hant": "🔑 你發佈了新的群密鑰。"],
        "SecutgGroupKeyChangedAccept": ["en": "Accept the new key", "zh-Hans": "接受新密钥", "zh-Hant": "接受新密鑰"],
        "SecutgGroupKeyChangedHint": ["en": "A new key from the same person means one of two things and this app cannot tell which. It may be their new phone. It may be somebody else sending in their name. Accept it if you know they changed device, or ask them before you do. Once accepted, that key can read everything sent in this group from then on.", "zh-Hans": "同一个人换了密钥，只有两种可能，而这个软件分不出是哪一种：可能是他换了新手机，也可能是别人在用他的名义。你确知他换了设备就接受，拿不准就先去问他一句。一旦接受，那把钥匙就能读到这个群之后的全部消息。", "zh-Hant": "同一個人換了密鑰，只有兩種可能，而這個軟體分不出是哪一種：可能是他換了新手機，也可能是別人在用他的名義。你確知他換了裝置就接受，拿不準就先去問他一句。一旦接受，那把鑰匙就能讀到這個群之後的全部訊息。"],
        "SecutgGroupKeyChangedLine": ["en": "{name} announced a different key from the one on file. Nothing was changed. Until you accept it, {name} gets no copy of the group key.", "zh-Hans": "{name} 公布的密钥和之前登记的那把不一样。这里什么都没有改。在你同意之前，{name} 拿不到这个群的钥匙。", "zh-Hant": "{name} 公布的密鑰和之前登記的那把不一樣。這裡什麼都沒有改。在你同意之前，{name} 拿不到這個群的鑰匙。"],
        "SecutgGroupKeyConfirming": ["en": "🔑 A new group key arrived. Confirming the sender is an admin…", "zh-Hans": "🔑 收到新的群密钥，正在确认发布者是否为本群管理员…", "zh-Hant": "🔑 收到新的群密鑰，正在確認發佈者是否為本群管理員…"],
        "SecutgGroupKeyCreatedTitle": ["en": "Group key created, encryption is on", "zh-Hans": "群密钥已生成，加密已开启", "zh-Hant": "群組金鑰已產生，加密已開啟"],
        "SecutgGroupKeyNotAdmin": ["en": "🔑 {name} is not an admin of this group. Key ignored.", "zh-Hans": "🔑 {name} 不是本群管理员，已忽略这条密钥。", "zh-Hant": "🔑 {name} 不是本群管理員，已忽略這條密鑰。"],
        "SecutgGroupKeyNotAuto": ["en": "🔑 This key is not for automatic pairing. Ignored.", "zh-Hans": "🔑 这条密钥不属于自动配对模式，已忽略。", "zh-Hant": "🔑 這條密鑰不屬於自動配對模式，已忽略。"],
        "SecutgGroupKeyOfflineTitle": ["en": "Si4Gram group key (enter offline)", "zh-Hans": "Si4Gram 群密钥（线下录入）", "zh-Hant": "Si4Gram 群組金鑰（線下錄入）"],
        "SecutgGroupKeyStale": ["en": "🔑 An older group key, already superseded. Ignored.", "zh-Hans": "🔑 这是更早的一条群密钥，已被取代，忽略。", "zh-Hant": "🔑 這是更早的一條群密鑰，已被取代，忽略。"],
        "SecutgGroupPwAdopted": ["en": "🔒 The admin set a group password. You will be asked for it when opening this group.", "zh-Hans": "🔒 管理员为本群设置了群密码，打开群时需要输入。", "zh-Hant": "🔒 管理員為本群設定了群密碼，打開群時需要輸入。"],
