        "SecutgImported": ["en": "Key imported, encryption is on", "zh-Hans": "密钥已导入，加密已开启", "zh-Hant": "金鑰已匯入，加密已開啟"],
        "SecutgIntroStart": ["en": "Start Messaging", "zh-Hans": "开始聊天", "zh-Hant": "開始聊天"],
        "SecutgIntroText1": ["en": "Plain text in your chat window. Ciphertext on the wire.", "zh-Hans": "聊天窗口全是明文，线上全是密文。", "zh-Hant": "聊天視窗全是明文，線上全是密文。"],
        "SecutgIntroText2": ["en": "Keys live only on your devices. No server ever sees the plain text. Works in private chats and groups.", "zh-Hans": "钥匙只在你的设备上，服务器永远拿不到明文。私聊和群聊都可以。", "zh-Hant": "鑰匙只在你的裝置上，伺服器永遠拿不到明文。私聊和群組都可以。"],
        "SecutgIntroText3": ["en": "Automatic pairing is the easy way. Scanning a QR code in person is the strict way.", "zh-Hans": "自动配对最方便，当面扫码最严格。", "zh-Hant": "自動配對最方便，當面掃碼最嚴格。"],
        "SecutgIntroText4": ["en": "Lost your phone? One phrase makes every device destroy its keys and sign out.", "zh-Hans": "手机丢了，一句密语就让所有设备销毁钥匙、退出登录。", "zh-Hant": "手機丟了，一句密語就讓所有裝置銷毀鑰匙、登出。"],
        "SecutgIntroText5": ["en": "Long texts and images can live on a server you run. You decide how long they are kept and when they are deleted.", "zh-Hans": "长文和图片可以存在你自己的服务器上，保存多久、何时删除由你决定。", "zh-Hant": "長文和圖片可以存在你自己的伺服器上，保存多久、何時刪除由你決定。"],
        "SecutgIntroText6": ["en": "Si4Gram is built on the Telegram API and is not affiliated with Telegram. Sign in with your existing Telegram account.", "zh-Hans": "Si4Gram 基于 Telegram API 开发，与 Telegram 无关联。用你现有的 Telegram 账号登录即可。", "zh-Hant": "Si4Gram 基於 Telegram API 開發，與 Telegram 無關聯。用你現有的 Telegram 帳號登入即可。"],
        "SecutgIntroTitle1": ["en": "Si4Gram", "zh-Hans": "Si4Gram", "zh-Hant": "Si4Gram"],
        "SecutgIntroTitle2": ["en": "Real end-to-end encryption", "zh-Hans": "真正的端到端加密", "zh-Hant": "真正的端對端加密"],
        "SecutgIntroTitle3": ["en": "Encrypted groups too", "zh-Hans": "群聊也能加密", "zh-Hant": "群組也能加密"],
        "SecutgIntroTitle4": ["en": "One-tap emergency wipe", "zh-Hans": "一键紧急擦除", "zh-Hant": "一鍵緊急擦除"],
        "SecutgIntroTitle5": ["en": "Your content stays off Telegram", "zh-Hans": "聊天内容不留在 Telegram", "zh-Hant": "聊天內容不留在 Telegram"],
