        "SecutgInviteMemberVerified": ["en": "encrypted · safety code verified", "zh-Hans": "已加密 · 安全码已核对", "zh-Hant": "已加密 · 安全碼已核對"],
        "SecutgInviteNeedsEncryption": ["en": "A group invite can only be sent in an encrypted private chat", "zh-Hans": "入群邀请只能在已加密的私聊里发送", "zh-Hant": "入群邀請只能在已加密的私聊裡傳送"],
